"""
    Get position of the ears from the app slider
    args:
        e   input from app slider
    returns:
        the angular position of the ear
    """
def get_ears_pos(e: Any) -> object {
    ears_range = 50;
    ears_offset = 100;
    e_pos = ((e - 50) * (ears_range / 50.0)) + ears_offset;
    return e_pos;
}

